import{_ as t,d as i,e as o,x as n}from"./chunks/framework.BRr8VP3a.js";const f=JSON.parse('{"title":"A.4 HV04 Generative Node (Full Interface Card)","description":"","frontmatter":{"title":"A.4 HV04 Generative Node (Full Interface Card)","xkChars":0,"xkWords":1136},"headers":[],"relativePath":"en/theory/appendix-a/a-04.md","filePath":"en/theory/appendix-a/a-04.md"}'),a={name:"en/theory/appendix-a/a-04.md"};function r(d,e,s,c,l,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<div class="theory-source"><h1 id="section-a-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">A.4</span><span class="xk-num__gap"></span></span>HV04 Generative Node (Full Interface Card) <a class="header-anchor" href="#section-a-4" aria-label="Permalink to &quot;A.4 HV04 Generative Node (Full Interface Card) {#section-a-4}&quot;">​</a></h1><p>A. Identity, Proposition, and Scope</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Interface ID (<code>id</code>)</td><td>HV04</td></tr><tr><td>Qualified ID (<code>qualified_id</code>)</td><td><code>human_variable:HV04</code></td></tr><tr><td>Name (<code>name</code>)</td><td>Generative Node</td></tr><tr><td>Claim type (<code>claim_type</code>)</td><td>H</td></tr><tr><td>Contract role (<code>contract_role</code>)</td><td><code>human_variable_interface</code></td></tr><tr><td>Proposition (<code>proposition</code>)</td><td>Generation must be separated into generative condition GC, generative subject GS, and generative event GE. Emergent generation can occur without an identifiable subject.</td></tr><tr><td>Scope (<code>scope</code>)</td><td>Formation of new actions, organizations, institutions, or state transitions in human structures</td></tr><tr><td>Conditions for suspension (<code>pause_condition</code>)</td><td>Suspend the relevant claims about the subject or the type when a condition is personified, an event is treated as a subject, or an entity is classified as a generative subject without grounds. R0 may still register candidate GC, GS, and GE and a status of unidentified subject separately. Failure to identify a subject does not establish that there is none.</td></tr></tbody></table></div><p>B. Formal Dependencies and Limits on Conclusions</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Inferential dependencies (<code>inferential_requires</code>)</td><td>None (empty set)</td></tr><tr><td>Protocol dependencies (<code>protocol_requires</code>)</td><td>1. EVIDENCE<br>2. SOURCE</td></tr><tr><td>Qualification/specialization (<code>specializes</code>)</td><td>None (empty set)</td></tr><tr><td>References to applicable objects (<code>applies_to</code>)</td><td>None (empty set)</td></tr><tr><td>Conditional support routes (<code>conditional_support_routes</code>)</td><td>1. route_id=HV04-R0-generation-typing;<br>claim_level=descriptive_classification;<br>when=The required fields for GC, GS, and GE can be registered separately, and emergence without a subject and the status of an unidentified subject are retained;<br>additional_inferential_requires=None (empty set);<br>additional_protocol_requires=None (empty set);<br>allowed_conclusion=Register a candidate generative condition, candidate generative subject, and candidate generative event separately. None may substitute for another;<br>result_ceiling=Classification by strong type only. The existence of a condition, subject, or event does not establish either of the other two or a causal mechanism of generation.<br>2. route_id=HV04-R1-generation-mechanism;<br>claim_level=mechanism_explanation;<br>when=A pre-registered G2-instance identifies an above-threshold effect of GC, GS, or a channel of emergence without a subject on the specified GE state transition;<br>additional_inferential_requires=G2-instance;<br>additional_protocol_requires=CAUSAL, E4;<br>allowed_conclusion=Register a candidate mechanism of generation and its GC, GS, and GE classifications for the specified scale, window, and channel;<br>result_ceiling=Do not personify conditions, infer a subject backward from an event, or infer normative justification, responsibility, or authorization from the fact of generation.</td></tr><tr><td>Permitted inferences (<code>allowed_inference</code>)</td><td>1. Conditional paths of generation. 2. Generation with or without a subject</td></tr><tr><td>Prohibited leaps (<code>prohibited_leap</code>)</td><td>1. Attributing intent to a technology or a crisis<br>2. Assuming a generative subject automatically has continuing authorization</td></tr></tbody></table></div><p>C. Nine-Axis Scale and Object Contract</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Nine-axis scale profile (<code>scale_profile</code>)</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;. A=Aggregation level covers units of exposure to conditions, action by subjects, and generative events, with their respective populations of cases, distributions, and aggregation rules. X=Spatial extent covers sites of generation, organizational or platform boundaries, areas of diffusion, and cross-domain environments. T=Time span covers the period of accumulation of conditions, the window of the subject’s action, the time of the event, and diffusion lag. O=Organizational level covers roles in action, generative teams, organizations, institutions, and governance ecologies. C=Causal level covers generative events, mechanisms of interaction between subjects and conditions, meso-level structures of generation, institutional arrangements, and systemic conditions. R=Resolution covers the original conditions, actions, and events, sequences of generation, individual cases, outcome distributions, transition metrics, and summaries. Record compression loss as well. I=Scope of influence covers direct participants in generation, people taking up the work, indirectly affected people, second-order consequences, and impacts across domains and generations. N=Network topology scope covers propagation of conditions, collaboration among subjects, diffusion of events, and emergent connections. J=Scope of jurisdiction and authorization requires separate authorization records for identification of generation, initiation of change, commitment of resources, and action concerning diffusion. Register scales separately for GC, GS, and GE</td></tr><tr><td>Effective object (<code>effective_object</code>)</td><td>A combination of conditions, subjects, and events that forms a detectable state transition</td></tr><tr><td>Scale invariants (<code>scale_invariants</code>)</td><td>1. Separation of GC, GS, and GE as strong types</td></tr><tr><td>Required additions for scale elevation (<code>required_scale_additions</code>)</td><td>1. New units and populations<br>2. Relations of representation<br>3. Kinds of responsibility<br>4. External impacts</td></tr><tr><td>What changes with scale (<code>changing_semantics</code>)</td><td>1. Generative subjects, conditions, and events can change with scale</td></tr><tr><td>Inapplicable objects (<code>non_applicable_objects</code>)</td><td>1. Stable descriptions without formation of a new state or a claim about generation</td></tr><tr><td>Prohibited elevations (<code>forbidden_elevation</code>)</td><td>1. Elevating a condition or an event to a subject with intent</td></tr></tbody></table></div><p>D. State, Evidence, and Variable Flows</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>State set (<code>state</code>)</td><td>1. Potential<br>2. Triggered<br>3. Forming<br>4. Interrupted<br>5. Diffusing</td></tr><tr><td>Observables (<code>observables</code>)</td><td>1. Records of when candidate conditions appear, change, or are removed<br>2. The generative subject’s capabilities, authorization, decisions, and actual actions<br>3. The pre-registered state transition from before to after the generative event<br>4. Records of the bridge from local interaction to aggregate outcome in emergence without a subject</td></tr><tr><td>Evidence requirements (<code>evidence</code>)</td><td>1. Records of initiation<br>2. Windows for conditions<br>3. Actions by subjects<br>4. Mechanisms of interaction without a subject</td></tr><tr><td>Input dependencies and interface content (<code>input_dependencies</code>)</td><td>1. Orientation anchor. 2. Resources and institutional conditions. 3. Causal contract</td></tr><tr><td>Output effects and variable flows (<code>output_effects</code>)</td><td>1. Need for uptake. 2. State transitions. 3. The start of a chain of responsibility</td></tr><tr><td>Time window and lag (<code>time_window_and_lag</code>)</td><td>Register accumulation of conditions, triggering events, and lags in formation</td></tr><tr><td>Uncertainty (<code>uncertainty</code>)</td><td>Record joint generation, emergence without a subject, and subjects that cannot be identified</td></tr><tr><td>Local exclusion zone (<code>local_exclusion_zone</code>)</td><td>Overlooked informal initiators and affected positions</td></tr><tr><td>Affected positions (<code>affected_positions</code>)</td><td>1. Initiators<br>2. People taking up the work<br>3. Beneficiaries<br>4. People affected</td></tr></tbody></table></div><p>E. Uptake, Responsibility, Normative Status, Ceilings, and Correction</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Uptake carriers (<code>carrier</code>)</td><td>1. Initiators<br>2. Procedures<br>3. Technical facilities<br>4. Relationship networks</td></tr><tr><td>Responsible parties (<code>responsible_subject</code>)</td><td>1. Those who actually act. 2. Decision makers. 3. Parties granting authorization</td></tr><tr><td>Normative status (<code>normative_status</code>)</td><td>The fact of generation does not establish normative justification or a complete attribution of responsibility</td></tr><tr><td>Judgment ceiling (<code>judgment_ceiling</code>)</td><td>Up to the level of explanation when the mechanism chain is complete</td></tr><tr><td>Action ceiling (<code>action_ceiling</code>)</td><td>This variable produces only candidate classifications for GC, GS, and GE, descriptions of state transitions, and needs for more evidence. It does not authorize starting, spreading, or stopping a generative process. Any real-world adjustment separately requires C12, explicit N premises at runtime, J authorization, and O procedures</td></tr><tr><td>Counterexamples (<code>counterexamples</code>)</td><td>1. A technological condition is incorrectly described as a generative subject with a goal<br>2. An emergent process without a unified initiator is forced into an attribution to one visible person</td></tr><tr><td>Appeal (<code>appeal</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, people classified as generative subjects can challenge attributions of intent, role, and authorization through a safe, accessible channel with anti-retaliation protection. This triggers review independent of the original classification or decision chain</td></tr><tr><td>Rollback (<code>rollback</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, once rollback is authorized, the designated responsible party must within the stated deadline correct the GC, GS, and GE types and actually remove erroneous attributions of intent or responsibility and their downstream effects. Preserve versions and verification of completion</td></tr></tbody></table></div></div>',1)])])}const b=t(a,[["render",r]]);export{f as __pageData,b as default};
